actions.script:
const rr = ec.resource.getLocationReference ? ec.resource.getLocationReference(imageLocation) : null;
if (!rr) {
    ec.message.addError(`Could not resolve image location ${imageLocation}.`);
    return;
}
let imageBytes = null;
if (rr.openStream) {
    rr.openStream().withStream((stream) => { imageBytes = stream.bytes; });
}
imageBase64 = imageBytes && imageBytes.encodeBase64 ? imageBytes.encodeBase64().toString() : "";
const baseUrl = (openVlaBaseUrl || "http://openvla:8000").replace(/\/+$/, "");
openVlaLocation = apiKey ? `${baseUrl}/act?apiKey=${encodeURIComponent(apiKey)}` : `${baseUrl}/act`;

const rr = ec.resource.getLocationReference ? ec.resource.getLocationReference(imageLocation) : null;
if (!rr) {
    ec.message.addError(`Could not resolve image location ${imageLocation}.`);
    return;
}
let imageBytes = null;
if (rr.openStream) {
    rr.openStream().withStream((stream) => { imageBytes = stream.bytes; });
}
imageBase64 = imageBytes && imageBytes.encodeBase64 ? imageBytes.encodeBase64().toString() : "";
const baseUrl = (openVlaBaseUrl || "http://openvla:8000").replace(/\/+$/, "");
openVlaLocation = apiKey ? `${baseUrl}/ground?apiKey=${encodeURIComponent(apiKey)}` : `${baseUrl}/ground`;

const normalizeNumberList = (value, fieldName, minSize = null) => {
    if (value == null) return null;
    const sourceList = Array.isArray(value) ? value : [value];
    const normalized = [];
    for (let idx = 0; idx < sourceList.length; idx++) {
        const entry = sourceList[idx];
        if (entry == null || String(entry).trim() === "") {
            ec.message.addError(`${fieldName}[${idx}] is empty.`);
            return null;
        }
        normalized.push(toDecimal(String(entry)));
    }
    if (minSize != null && normalized.length < minSize) {
        ec.message.addError(`${fieldName} must contain at least ${minSize} values.`);
        return null;
    }
    return normalized;
};

const boundingBoxList = normalizeNumberList(groundingResult ? groundingResult.boundingBox : null, "boundingBox", 4);
const centerList = normalizeNumberList(groundingResult ? groundingResult.center : null, "center", 2);
const targetPoseList = normalizeNumberList(groundingResult ? groundingResult.targetPose : null, "targetPose",
    returnTargetPose ? (targetPoseDimension || 6) : null);

if (!boundingBoxList && !centerList && !targetPoseList) {
    ec.message.addError(`OpenVLA grounding response for device ${deviceId} did not contain boundingBox, center, or targetPose.`);
    return;
}

boundingBox = boundingBoxList;
center = centerList;
targetPose = targetPoseList;
goalPose = targetPoseList;
objectLabel = groundingResult ? groundingResult.objectLabel : null;
confidence = groundingResult ? groundingResult.confidence : null;
coordinateSystem = (groundingResult && groundingResult.coordinateSystem) || "image-pixel";
modelId = groundingResult ? groundingResult.modelId : null;

if.script:
const createVector = (name, description, vectorSpaceEnumId, purposeEnumId, values) => {
    if (!values || !values.length) return null;
    const vectorValue = ec.entity.makeValue("moqui.math.Vector");
    vectorValue.setAll({
        vectorTypeEnumId: "VtOrdinary",
        purposeEnumId: purposeEnumId,
        vectorSpaceEnumId: vectorSpaceEnumId,
        name: name,
        description: description,
        dimension: values.length
    });
    vectorValue.setSequencedIdPrimary();
    vectorValue.create();
    for (let idx = 0; idx < values.length; idx++) {
        const componentValue = ec.entity.makeValue("moqui.math.VectorComponent");
        componentValue.setAll({
            vectorId: vectorValue.vectorId,
            dimensionIndex: idx,
            componentTypeEnumId: "VctCanonical",
            realValue: values[idx]
        });
        componentValue.setSequencedIdPrimary();
        componentValue.create();
    }
    return vectorValue.vectorId;
};

const dcId = (deviceContent && deviceContent.deviceContentId) ? deviceContent.deviceContentId : "";
if (saveBoundingBox && boundingBox) {
    boundingBoxMinVectorId = createVector(
        `bbox_min_${deviceId}`,
        `Visual grounding bounding-box min corner for device ${deviceId}, image ${dcId}`,
        imageVectorSpaceEnumId || "EuclideanSpace2D",
        "VpPosition",
        [boundingBox[0], boundingBox[1]]
    );
    boundingBoxMaxVectorId = createVector(
        `bbox_max_${deviceId}`,
        `Visual grounding bounding-box max corner for device ${deviceId}, image ${dcId}`,
        imageVectorSpaceEnumId || "EuclideanSpace2D",
        "VpPosition",
        [boundingBox[2], boundingBox[3]]
    );
}
if (saveCenter && center) {
    centerVectorId = createVector(
        `bbox_center_${deviceId}`,
        `Visual grounding center point for device ${deviceId}, image ${dcId}`,
        imageVectorSpaceEnumId || "EuclideanSpace2D",
        "VpPosition",
        center
    );
}
if (saveTargetPose && targetPose) {
    targetPoseVectorId = createVector(
        `target_pose_${deviceId}`,
        `Target TCP pose inferred from visual grounding for device ${deviceId}, image ${dcId}`,
        targetPoseVectorSpaceEnumId || "EngTcpPose6Dof",
        "VpPosition",
        targetPose
    );
}

actions.script:
const normalizePose = (config, fieldName) => {
    if (!Array.isArray(config)) {
        ec.message.addError(`${fieldName} must be an Array with exactly 6 numeric values.`);
        return null;
    }
    if (config.length !== 6) {
        ec.message.addError(`${fieldName} must contain exactly 6 numeric values, found ${config.length}.`);
        return null;
    }
    const normalized = [];
    for (let i = 0; i < config.length; i++) {
        const val = Number(config[i]);
        if (isNaN(val)) {
            ec.message.addError(`${fieldName}[${i}] must be numeric, found '${config[i]}'.`);
            return null;
        }
        normalized.push(val);
    }
    return normalized;
};

if (!startPose) { ec.message.addError("Missing startPose."); return; }
if (!goalPose) { ec.message.addError("Missing goalPose."); return; }

startPoseList = normalizePose(startPose, "startPose");
goalPoseList = normalizePose(goalPose, "goalPose");
if (!startPoseList || !goalPoseList) return;

mathModelRunParameters = JSON.stringify({ startPose: startPoseList, goalPose: goalPoseList });
trajectoryLabel = trajectoryName || null;

try {
    const tInferStart = Date.now();
    const nWaypoints = 10;
    const generatedWaypoints = [];
    for (let i = 0; i < nWaypoints; i++) {
        const alpha = nWaypoints > 1 ? i / (nWaypoints - 1) : 0;
        const waypoint = [];
        for (let j = 0; j < 6; j++) {
            const val = startPoseList[j] + alpha * (goalPoseList[j] - startPoseList[j]);
            waypoint.push(Math.round(val * 10000) / 10000);
        }
        generatedWaypoints.push(waypoint);
    }
    waypoints = generatedWaypoints;
    waypointCount = nWaypoints;
    inferenceLatencyMs = Date.now() - tInferStart;
} catch (err) {
    const elapsed = Date.now() - t0;
    const runRef = ec.entity.find("moqui.math.MathModelRun").condition("mathModelRunId", runId).one();
    if (runRef) {
        runRef.setAll({
            endDate: ec.user.nowTimestamp,
            runningTimeMillis: elapsed,
            hasError: "Y",
            errors: err.message || String(err)
        });
        runRef.update();
    }
    ec.message.addError(`Trajectory inference failed: ${err.message || err}`);
    return;
}

set.from:
{vectorSpaceEnumId: 'EngTcpPose6Dof', codomainTypeEnumId: 'AfctVector',
                dataStorageEnumId: 'AfdsPointTable', purposeEnumId: 'AfpRobotMotion', interpolationEnumId: 'AfiAIPath',
                name: trajectoryLabel, description: '6-DOF TCP waypoint trajectory from AI planner'}

{approximatedFunctionId: approximatedFunctionId, sampleCode: 'WP' + String(waypointIndex).padStart(4, '0'),
                    sampleName: 'Waypoint ' + waypointIndex, sequenceNum: waypointIndex, sampleTypeEnumId: sampleTypeEnumId,
                    sampleVectorId: waypointVectorId}

{mathModelId: mathModelId, dataTypeEnumId: 'MmdtApproxFunc',
                purposeEnumId: 'MmdpModelOutputs', generatedByRunId: runId, approximatedFunctionId: approximatedFunctionId,
                sequenceNum: 1}

actions.script:
const elapsed = Date.now() - t0;
const totalDurationSec = elapsed > 0 ? elapsed / 1000.0 : 0.001;
resultsJson = JSON.stringify({ approximatedFunctionId: approximatedFunctionId, waypointCount: waypointCount });

const runRef = ec.entity.find("moqui.math.MathModelRun").condition("mathModelRunId", runId).one();
if (runRef) {
    runRef.setAll({
        endDate: ec.user.nowTimestamp,
        runningTimeMillis: elapsed,
        approximatedFunctionId: approximatedFunctionId,
        results: resultsJson
    });
    runRef.update();
}

perfFields = {
    mathModelRunId: runId,
    totalDurationSec: totalDurationSec,
    inferenceLatencyMs: Number(inferenceLatencyMs || 0),
    throughputSamplesSec: Number(waypointCount || 0) / totalDurationSec
};
